mapper.select:
select distinct std_eprf.UPLOAD_FILENAME fileName, TO_CHAR(std_eprf.UPLOAD_DT, 'MM/DD/YYYY') submittedDate, TRUNC(std_eprf.UPLOAD_DT), CASE WHEN provider_hcsid is not null THEN b.PROVIDER_LNAME || ', ' || b.PROVIDER_FNAME ELSE C.USER_LNAME || ', ' || c.USER_FNAME END submittedBy
from ${tableName} std_eprf, PORTAL_PROVIDERS b, portal_provider_user_mapping c where
std_eprf.REVIEW_DT is null and
std_eprf.current_process_Status = #{processStatus}
AND std_eprf.FILE_TYPE_CD = #{fileType}
and std_eprf.UPLOAD_ID = b.provider_hcsid(+) AND std_eprf.upload_id = c.user_hcsid(+) order by TRUNC(std_eprf.UPLOAD_DT) desc

mapper.update:
		update RAW_EPRF_OOC_UPLOAD set current_process_STatus = #{processStatus}, REVIEW_ID = #{workerId}, REVIEW_DATE = SYSDATE where

		current_process_STatus = 16 

		and UPLOAD_FILENAME in


						        	#{fileName}




                    AND FILE_TYPE_CD =  #{documentFileType}

update STD_EPRF_OOC_UPLOAD set
CONFIRMATORY_RESULT_REPORTED = #{CONFIRMATORY_RESULT_REPORTED}, SUBMITTING_PROVIDER_PRESENT = #{SUBMITTING_PROVIDER_PRESENT}, REVIEW_COMMENT = #{REVIEW_COMMENT}, INTERNAL_CONCLUSION=#{INTERNAL_CONCLUSION}, CARE_STATUS =#{CARE_STATUS}
, COMPLETE_DATE = SYSDATE,
NYS_EHARS_STATENO=trim(upper(#{NYS_EHARS_STATENO,jdbcType=VARCHAR})), NYC_EHARS_STATENO=trim(upper(#{NYC_EHARS_STATENO,jdbcType=VARCHAR})), NYC_CITY_NO=trim(upper(#{NYC_CITY_NO,jdbcType=VARCHAR})), LAST_HIV_LAB_TYPE=trim(upper(#{LAST_HIV_LAB_TYPE,jdbcType=VARCHAR})), LAST_HIV_LAB_DATE=TO_DATE(trim(upper(#{LAST_HIV_LAB_DATE,jdbcType=VARCHAR})), 'MM/DD/YYYY'), LAST_HIV_LAB_RESULT=trim(upper(#{LAST_HIV_LAB_RESULT,jdbcType=VARCHAR})), MONTHS_SINCE_LAST_HIV_LAB=trim(upper(#{MONTHS_SINCE_LAST_HIV_LAB,jdbcType=DECIMAL})), NYS_VITAL_STATUS=trim(upper(#{NYS_VITAL_STATUS,jdbcType=VARCHAR})), NYC_VITAL_STATUS=trim(upper(#{NYC_VITAL_STATUS,jdbcType=VARCHAR})), MEETS_CASE_DEFINITION_IN=trim(upper(#{MEETS_CASE_DEFINITION_IN,jdbcType=VARCHAR})), MEETS_CDC_ELIG_ID=trim(upper(#{MEETS_CDC_ELIG_ID,jdbcType=VARCHAR}))
where DOCUMENT_ID = #{DOCUMENT_ID}

update EPRF_PROV_PORTAL_FILE_UPLOAD set 


	FILE_CLIENT_FEEDBACK_DATE = TO_DATE(#{FILE_CLIENT_FEEDBACK_DATE,jdbcType=VARCHAR}, 'MM/DD/YYYY'),


FILENAME = #{FILENAME}

where FILENAME = #{FILENAME}
